/**
 * An Excalidraw drawing bound to a source: what the source has to be, and the
 * note the Excalidraw plugin reads it from.
 *
 * A drawing is not reviewed. A document's update arrives as cards because a
 * person reads and edits it; a board generated by a script is replaced whole,
 * or not at all, and a card for one line of minified JSON would be the whole
 * board anyway.
 *
 * Nothing about a drawing's check is kept in the plugin's data: the source's
 * hash and validator live in the note's own frontmatter, beside the binding,
 * and are written only when the source changed. A device that reads the note
 * knows as much as the device that wrote it.
 *
 * The note is the plugin's own `.excalidraw.md` layout. Its pictures are
 * vault files listed under "Embedded Files" rather than base64 inside the
 * drawing, which is what keeps a board of a hundred screenshots a note of a
 * few hundred kilobytes; the drawing itself is written as plain JSON, and the
 * Excalidraw plugin compresses it the next time it saves.
 */

import { splitFrontmatter } from "./frontmatter-block";
import { t } from "../i18n";
import { checkEtag } from "./sync-request";
import { formatUpdatedAt, SYNC_UPDATED_KEY } from "./sync-frontmatter";
import { fileNameParts } from "./file-glyph";
import { frontmatterLine, SYNC_FRONTMATTER_KEY } from "./sync-source";

/** Hash of the source as last written into the note. */
export const DRAWING_HASH_KEY = "schreibstubeSourceHash";
/** The source's validator, so an unchanged board costs no download. */
export const DRAWING_ETAG_KEY = "schreibstubeSourceEtag";
/** What makes the Excalidraw plugin open the note as a drawing. */
const PLUGIN_KEY = "excalidraw-plugin";

export const MAX_DRAWING_ELEMENTS = 50_000;
export const MAX_DRAWING_IMAGES = 2_000;

/**
 * An element or picture id. It becomes a block reference (`^id`) and a file
 * name, so it is held to what both can carry; Excalidraw's own ids and a
 * content hash both fit.
 */
const ID = /^[A-Za-z0-9_-]{1,128}$/;

const IMAGE_EXTENSIONS: Readonly<Record<string, string>> = {
  "image/png": "png",
  "image/jpeg": "jpg",
  "image/webp": "webp",
  "image/gif": "gif",
  "image/svg+xml": "svg"
};

const BASE64 = /^[A-Za-z0-9+/]*={0,2}$/;

export interface DrawingImage {
  id: string;
  extension: string;
  base64: string;
}

export interface DrawingText {
  id: string;
  text: string;
}

export interface Drawing {
  /** The scene without its pictures, as the note's JSON block holds it. */
  scene: Record<string, unknown>;
  texts: DrawingText[];
  images: DrawingImage[];
}

export type DrawingResult = { ok: true; drawing: Drawing } | { ok: false; reason: string };

/** Read a fetched source as a drawing, or say why it is not one. */
export function checkDrawing(text: string): DrawingResult {
  const messages = t().source;

  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    return { ok: false, reason: messages.drawingUnreadable };
  }
  if (!isRecord(parsed) || parsed.type !== "excalidraw" || !Array.isArray(parsed.elements)) {
    return { ok: false, reason: messages.drawingUnreadable };
  }

  const elements: unknown[] = parsed.elements;
  const files = parsed.files ?? {};
  if (!isRecord(files)) return { ok: false, reason: messages.drawingUnreadable };
  const entries = Object.entries(files);
  if (elements.length > MAX_DRAWING_ELEMENTS || entries.length > MAX_DRAWING_IMAGES) {
    return { ok: false, reason: messages.drawingTooMany };
  }

  const texts: DrawingText[] = [];
  for (const element of elements) {
    if (!isRecord(element) || typeof element.id !== "string" || !ID.test(element.id)) {
      return { ok: false, reason: messages.drawingUnreadable };
    }
    if (element.type !== "text" || element.isDeleted === true) continue;
    const text = [element.rawText, element.originalText, element.text].find(
      (value): value is string => typeof value === "string"
    );
    if (text !== undefined && text.trim().length > 0) texts.push({ id: element.id, text });
  }

  const images: DrawingImage[] = [];
  for (const [id, file] of entries) {
    const image = readImage(id, file);
    if (image === null) return { ok: false, reason: messages.drawingImage(id.slice(0, 40)) };
    images.push(image);
  }

  return { ok: true, drawing: { scene: { ...parsed, files: {} }, texts, images } };
}

function readImage(id: string, file: unknown): DrawingImage | null {
  if (!ID.test(id) || !isRecord(file) || typeof file.dataURL !== "string") return null;

  const mimeType = typeof file.mimeType === "string" ? file.mimeType : "";
  const extension = IMAGE_EXTENSIONS[mimeType];
  const prefix = `data:${mimeType};base64,`;
  if (extension === undefined || !file.dataURL.startsWith(prefix)) return null;

  const base64 = file.dataURL.slice(prefix.length);
  return BASE64.test(base64) ? { id, extension, base64 } : null;
}

/** What a drawing's frontmatter says about the source as last written. */
export interface DrawingState {
  hash: string | null;
  etag: string;
}

export function drawingStateOf(frontmatter: Record<string, unknown> | undefined): DrawingState {
  const hash = frontmatter?.[DRAWING_HASH_KEY];
  // Without a hash there is nothing an "unchanged" answer could be trusted
  // against, so the validator is not sent and the board is fetched whole.
  if (typeof hash !== "string" || !/^[0-9a-f]{8}$/.test(hash)) return { hash: null, etag: "" };
  return { hash, etag: checkEtag(frontmatter?.[DRAWING_ETAG_KEY]) };
}

/** Whether a fetched source is a different board from the one in the note. */
export function isDrawingChange(state: DrawingState, sourceHash: string): boolean {
  return state.hash !== sourceHash;
}

/**
 * Whether the mirror wrote this note before, read off the note itself.
 *
 * What makes the pictures it lists the mirror's to replace and to retire. A
 * drawing someone made by hand and then bound lists pictures they pasted in,
 * and those are theirs whatever the board does next.
 */
export function isMirroredNote(noteText: string): boolean {
  return frontmatterLine(noteText, DRAWING_HASH_KEY) !== null;
}

/**
 * Where a drawing's pictures go: a folder beside it, named as the row reads.
 * `Projekte/Atlas.excalidraw.md` keeps them in `Projekte/Atlas/`.
 */
export function drawingImageFolder(notePath: string): string {
  const slash = notePath.lastIndexOf("/");
  const name = notePath.slice(slash + 1);
  const dot = name.lastIndexOf(".");
  const { stem } = fileNameParts(name, dot === -1 ? "" : name.slice(dot + 1));
  return `${notePath.slice(0, slash + 1)}${stem}`;
}

export function drawingImagePath(folder: string, image: DrawingImage): string {
  return `${folder}/${image.id}.${image.extension}`;
}

/**
 * The links a drawing note lists under "Embedded Files", as written: by the
 * mirror, or shortened by the Excalidraw plugin when it saved the note.
 *
 * What the mirror wrote last time is what it may replace and give up now. A
 * folder's name says nothing about whose files are in it — a person's own
 * `Projekte/Atlas/logo.png` sits exactly where the board's pictures would.
 */
export function listedImageLinks(noteText: string): string[] {
  const links: string[] = [];
  let inSection = false;
  for (const line of noteText.split(/\r?\n/)) {
    if (/^#{1,6}\s|^%%/.test(line)) {
      inSection = /^## Embedded Files\s*$/.test(line);
      continue;
    }
    const link = inSection
      ? /^[A-Za-z0-9_-]+: \[\[([^\]|#\n]+)(?:[|#][^\]\n]*)?\]\]\s*$/.exec(line)
      : null;
    if (link?.[1] !== undefined) links.push(link[1]);
  }
  return links;
}

/** The pictures the mirror wrote before and the board no longer shows. */
export function retiredImages(owned: readonly string[], kept: ReadonlySet<string>): string[] {
  return [...new Set(owned)].filter((path) => !kept.has(path));
}

export function decodeBase64(base64: string): Uint8Array<ArrayBuffer> {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

export function sameBytes(a: ArrayBuffer, b: Uint8Array): boolean {
  if (a.byteLength !== b.byteLength) return false;
  const left = new Uint8Array(a);
  return left.every((byte, i) => byte === b[i]);
}

export interface DrawingNoteInput {
  /** The note as it stands, for its frontmatter. */
  noteText: string;
  drawing: Drawing;
  /** Each picture's id and the vault path it was written to. */
  imagePaths: ReadonlyMap<string, string>;
  /** Hash of the source's text, which the note keeps. */
  sourceHash: string;
  etag: string;
  /**
   * Whether the source moved. A board written again because someone asked for
   * it — to mend a note damaged here — keeps the date its source last changed.
   */
  changed: boolean;
  now: Date;
}

/** The whole note a source becomes: its frontmatter kept, its body new. */
export function buildDrawingNote(input: DrawingNoteInput): string {
  const { block } = splitFrontmatter(input.noteText);
  const frontmatter = setFrontmatter(block, [
    // The Excalidraw plugin's own key, and the plugin's to write: a note
    // bound as a drawing already carries it, and only one that lost it is
    // given it back, or the plugin would open the board as text.
    [PLUGIN_KEY, "parsed", "missing"],
    [DRAWING_HASH_KEY, JSON.stringify(input.sourceHash)],
    [DRAWING_ETAG_KEY, input.etag.length > 0 ? JSON.stringify(input.etag) : null],
    ...(input.changed ? [[SYNC_UPDATED_KEY, formatUpdatedAt(input.now)] as Entry] : [])
  ]);
  return frontmatter + drawingBody(input.drawing, input.imagePaths);
}

/**
 * A drawing note bound to a source, written as text rather than through
 * Obsidian's frontmatter writer, so the write can go where an open drawing
 * cannot merge it (see the writer).
 */
export function withBinding(noteText: string, url: string): string {
  const { block, body } = splitFrontmatter(noteText);
  return setFrontmatter(block, [[SYNC_FRONTMATTER_KEY, JSON.stringify(url)]]) + body;
}

/**
 * A drawing note unbound: its source and what the mirror kept about it gone.
 * Left behind, the hash told a later binding that the board was already in
 * the note.
 */
export function withoutBinding(noteText: string): string | null {
  const { block, body } = splitFrontmatter(noteText);
  if (block.length === 0) return null;
  const next = setFrontmatter(block, [
    [SYNC_FRONTMATTER_KEY, null],
    [DRAWING_HASH_KEY, null],
    [DRAWING_ETAG_KEY, null]
  ]);
  return next === block ? null : next + body;
}

/**
 * The validator alone, for a source that answered in full with the board the
 * note already holds. Null when the note already says it.
 */
export function withDrawingEtag(noteText: string, etag: string): string | null {
  const { block, body } = splitFrontmatter(noteText);
  if (block.length === 0) return null;
  const next = setFrontmatter(block, [
    [DRAWING_ETAG_KEY, etag.length > 0 ? JSON.stringify(etag) : null]
  ]);
  return next === block ? null : next + body;
}

function drawingBody(drawing: Drawing, imagePaths: ReadonlyMap<string, string>): string {
  const lines = ["# Excalidraw Data", "", "## Text Elements"];

  // Listed for the reader and for search, and read back by the Excalidraw
  // plugin as the text of each element. A text that would end the section or
  // the comment around the drawing is left to the drawing's JSON.
  for (const { id, text } of drawing.texts) {
    if (/%%|```|^#{1,6}\s/m.test(text)) continue;
    lines.push(`${text} ^${id}`, "");
  }

  const embedded = drawing.images.flatMap((image) => {
    const path = imagePaths.get(image.id);
    return path === undefined ? [] : [`${image.id}: [[${path}]]`, ""];
  });
  if (embedded.length > 0) lines.push("## Embedded Files", ...embedded);

  // JSON cannot hold a raw line break inside a string, so no line of it can
  // close the fence.
  lines.push("%%", "## Drawing", "```json", JSON.stringify(drawing.scene), "```", "%%", "");
  return lines.join("\n");
}

/** A key, its value or null to remove it, and whether to write it only when missing. */
type Entry = [string, string | null] | [string, string, "missing"];

/**
 * Set or remove single-line keys in a frontmatter block, leaving every other
 * line as it was spelled. A key that was a list or a folded block loses its
 * continuation lines with it.
 */
function setFrontmatter(block: string, entries: Entry[]): string {
  const lines = block.length > 0 ? block.replace(/\r?\n$/, "").split(/\r?\n/) : ["---", "---"];
  const inner = lines.slice(1, -1);

  for (const [key, value, when] of entries) {
    const at = inner.findIndex((line) => line.startsWith(`${key}:`));
    if (when === "missing" && at !== -1) continue;
    let end = at + 1;
    if (at !== -1) {
      while (end < inner.length && /^(\s|- )/.test(inner[end] ?? "")) end += 1;
    }

    const replacement = value === null ? [] : [`${key}: ${value}`];
    if (at === -1) inner.push(...replacement);
    else inner.splice(at, end - at, ...replacement);
  }

  return ["---", ...inner, "---", ""].join("\n");
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
